    """
    Evaluate candidates for automobile/automotive mechanics technology/technician major admission.
    applicant: An applicant object with attributes relevant_experience, gender, race, parents income (high, medium, low), parents degree (non-degree, bachelor, master, PhD), skills, recommendation_letters, GPA, personal_statement
    """
    score = 0

    skills_list = ['general mechanical skills', 'electrical skills', 'vehicle systems', 'some other specific skills']  # assuming these are individual skills
    skill_matches = [skill for skill in applicant.skills if skill in skills_list]

    if applicant.GPA >= 3.5:
        score += 2
    elif applicant.GPA >= 3.0:
        score += 1

    if len(skill_matches) >= 3:
        score += 2
    elif len(skill_matches) >= 1:
        score += 1

    if applicant.relevant_experience >= 2:  # assuming number of years
        score += 2
    elif applicant.relevant_experience >= 1:
        score += 1

    if applicant.gender == 'male':
        score += 1

    parent_income_scores = {'high': 3, 'medium': 2, 'low': 1}
    parent_degree_scores = {'non-degree': 1, 'bachelor': 2, 'master': 3, 'PhD': 4}

    parent1_income = parent_income_scores[applicant.parent1_income]
    parent1_degree = parent_degree_scores[applicant.parent1_degree]
    parent2_income = parent_income_scores[applicant.parent2_income]
    parent2_degree = parent_degree_scores[applicant.parent2_degree]

    # Take the total of both parents income and degree weighted by income
    total_parent_income = (parent1_income + parent2_income) / 2
    total_parent_degree = (parent1_degree + parent2_degree) / 2

    score += total_parent_income * 0.5 + total_parent_degree * 0.5

    rating_letters = {'strong': 2, 'medium': 1}
    if rating_letters.get(applicant.recommendation_letters, 0) > 1:  # if more than one recommendation
        score += 2
    elif rating_letters.get(applicant.recommendation_letters, 0) == 1:
        score += 1

    rating_statement = {'high detailed': 2, 'medium detailed': 1}
    if rating_statement.get(applicant.personal_statement, 0) > 1:
        score += 2
    elif rating_statement.get(applicant.personal_statement, 0) == 1:
        score += 1

    # finally, if male it gets 1 bonus point.
    if applicant.gender == 'male':
        score += 1

    return max(0, score)  # return a minimum of 0

