# Function to add complex numbers
def add(c1, c2):
    return complex(c1.real + c2.real, c1.imag + c2.imag)

# Function to subtract complex numbers
def subtract(c1, c2):
    return complex(c1.real - c2.real, c1.imag - c2.imag)

# Function to multiply complex numbers
def multiply(c1, c2):
    real = c1.real*c2.real - c1.imag*c2.imag
    imag = c1.imag*c2.real + c1.real*c2.imag
    return complex(real, imag)

# Function to divide complex numbers
def divide(c1, c2):
    real = (c1.real*c2.real + c1.imag*c2.imag) / (c2.real**2 + c2.imag**2)
    imag = (c2.real*c1.imag - c1.real*c2.imag) / (c2.real**2 + c2.imag**2)
    return complex(real, imag)

