    elif applicant["recommendation_letters"] == 'medium':
        score += 1

    if applicant["personal_statement"] == 'excellent':
        score += 2
    elif applicant["personal_statement"] == 'good':
        score += 1

    score_grade = {
        (8,10): 'Excellent',
        (6,7): 'Good',
        (4,5): 'Average',
        (2,3): 'Poor',
        (0,1): 'Poor',
    }

    for key in score_grade.keys():
        if key[0] <= score <= key[1]:
            return score, score_grade[key]

