def line_to_dict(line):
    parts = line.split(',')
    return {'name': parts[0].strip(), 'age': int(parts[1].strip()), 'city': parts[2].strip()}

def read_file_to_dicts(filename):
    with open(filename, 'r') as file:
        return [line_to_dict(line) for line in file]

