def factorial(n):
    # Check if the input is a positive integer
    if not isinstance(n, int) or n < 0:
        raise ValueError("The input must be a positive integer")
    # Recursive case
    elif n > 1:
        return n * factorial(n-1)
    # Base case
    elif n == 1 or n == 0:
        return 1

